82	    /** Naskladnění od dodavatele. */
83	    public function receive(int $quantity): void
84	    {
85	        if ($quantity < 1) {
86	            throw new \InvalidArgumentException('Received quantity must be positive');
87	        }
88	
89	        $this->onHand += $quantity;
